562	  async function hasActiveCheckoutManagementOverride(
563	    actorAgentId: string,
564	    companyId: string,
565	    assigneeAgentId: string,
566	  ) {
567	    const allowedByGrant = await access.hasPermission(
568	      companyId,
569	      "agent",
570	      actorAgentId,
571	      "tasks:manage_active_checkouts",
572	    );
573	    if (allowedByGrant) return true;
574	
575	    const companyAgents = await agentsSvc.list(companyId);
576	    const agentsById = new Map(companyAgents.map((agent) => [agent.id, agent]));
577	    const actorAgent = agentsById.get(actorAgentId);
578	    if (!actorAgent) return false;
579	    if (canCreateAgentsLegacy(actorAgent)) return true;
580	
581	    // Reporting-chain managers may intervene in an agent's active checkout
582	    // without taking the task over. Peers must own the checkout/run first.
583	    let cursor: string | null = assigneeAgentId;
584	    for (let depth = 0; cursor && depth < 50; depth += 1) {
585	      const assignee = agentsById.get(cursor);
586	      if (!assignee) return false;
587	      if (assignee.reportsTo === actorAgentId) return true;
588	      cursor = assignee.reportsTo;
589	    }
590	
591	    return false;
592	  }
